#include <stdlib.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <string.h>

#define PIPE_SIZE 4096

int main() {
    int fd, pipefd[2];
    char *mapped;
    char payload[] = "This is a payload!";

    // Create a pipe
    if (pipe(pipefd) < 0) {
        perror("pipe");
        exit(EXIT_FAILURE);
