    // Memory-map the pipe
    mapped = mmap(NULL, PIPE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, pipefd[1], 0);
    if (mapped == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Write to the pipe (this is a simplified example)
    strcpy(mapped, payload);

    // Unmap and close
    munmap(mapped, PIPE_SIZE);
    close(pipefd[1]);

    return 0;
}
